class Solution:
    def discountPrices(self, sentence: str, discount: int) -> str:
        out = []
        for word in sentence.split(" "):
            if len(word) > 1 and word[0] == "$" and word[1:].isdigit():   # a price
                price = int(word[1:]) * (100 - discount) / 100
                word = f"${price:.2f}"
            out.append(word)
        return " ".join(out)
